// ═══════════════════════════════════════════════════════════════
// DCS Core — Component Registry & Theme Manager
// Single source of truth for all DCS infrastructure.
// ═══════════════════════════════════════════════════════════════
'use strict';

(function setupDCS() {
  var _registry = {};
  var _instanceCounter = {};

  // ── Get or create window.DCS ────────────────────────────
  window.DCS = window.DCS || {};

  // ── Registry ────────────────────────────────────────────
  window.DCS.register = function(name, controller) {
    _registry[name] = controller;
  };

  window.DCS._init = function(container) {
    container = container || document;
    var els = Array.prototype.slice.call(container.querySelectorAll('[data-dcs-component]:not([data-dcs-initialized])'));
    if (container.matches && container.matches('[data-dcs-component]:not([data-dcs-initialized])')) {
      els.unshift(container);
    }
    for (var i = 0; i < els.length; i++) {
      var el = els[i];
      var name = el.getAttribute('data-dcs-component');
      var ctrl = _registry[name];
      if (!ctrl) continue;
      if (!_instanceCounter[name]) _instanceCounter[name] = 0;
      _instanceCounter[name]++;
      el.setAttribute('data-dcs-instance', _instanceCounter[name]);
      el.setAttribute('data-dcs-initialized', '');
      if (ctrl.init) ctrl.init(el);
    }
  };

  window.DCS._registeredComponents = function() {
    return Object.keys(_registry);
  };

  // ── Toast ───────────────────────────────────────────────
  // Uses .toast-container / .toast / .toast-{type} classes from dcs-components.css
  window.DCS._showToast = function(message, type) {
    type = type || 'info';
    var container = document.querySelector('.toast-container');
    if (!container) {
      container = document.createElement('div');
      container.className = 'toast-container';
      document.body.appendChild(container);
    }
    // The container is a polite live region so screen readers announce toasts
    // as they arrive without stealing focus.
    if (!container.getAttribute('aria-live')) {
      container.setAttribute('aria-live', 'polite');
      container.setAttribute('aria-atomic', 'false');
    }

    var toast = document.createElement('div');
    toast.className = 'toast toast-' + type;
    toast.textContent = message;
    // Errors/warnings are assertive; everything else is a polite status.
    toast.setAttribute('role', (type === 'error' || type === 'warning' || type === 'danger') ? 'alert' : 'status');
    container.appendChild(toast);

    // Trigger entry animation (CSS: .toast.show = translateY(0), opacity: 1)
    requestAnimationFrame(function() {
      toast.classList.add('show');
    });

    setTimeout(function() {
      toast.classList.remove('show');
      setTimeout(function() {
        if (toast.parentNode) toast.parentNode.removeChild(toast);
      }, 300);
    }, 3000);
  };

  // ── Focus Management ────────────────────────────────────
  // Shared helpers so overlay components (modal, drawer, bottom sheet,
  // command palette) can trap focus consistently.
  var FOCUSABLE_SELECTOR =
    'a[href], area[href], button:not([disabled]), input:not([disabled]):not([type="hidden"]), ' +
    'select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"]), ' +
    '[contenteditable="true"]';

  // Visible, focusable elements inside a container, in DOM order.
  window.DCS._focusable = function(container) {
    var all = container.querySelectorAll(FOCUSABLE_SELECTOR);
    var out = [];
    for (var i = 0; i < all.length; i++) {
      var el = all[i];
      // Skip elements that are hidden (no layout box).
      if (el.offsetWidth > 0 || el.offsetHeight > 0 || el.getClientRects().length > 0) {
        out.push(el);
      }
    }
    return out;
  };

  // Trap keyboard focus inside `container`. Saves the element that had focus,
  // moves focus inside, and cycles Tab / Shift+Tab within. Returns a release()
  // function that removes the trap and restores focus to the trigger.
  window.DCS._trapFocus = function(container) {
    var previouslyFocused = document.activeElement;

    function onKeydown(e) {
      if (e.key !== 'Tab') return;
      var focusable = window.DCS._focusable(container);
      if (!focusable.length) {
        // Nothing focusable inside — keep focus on the container itself.
        e.preventDefault();
        return;
      }
      var first = focusable[0];
      var last = focusable[focusable.length - 1];
      var active = document.activeElement;
      if (e.shiftKey) {
        if (active === first || !container.contains(active)) {
          e.preventDefault();
          last.focus();
        }
      } else {
        if (active === last || !container.contains(active)) {
          e.preventDefault();
          first.focus();
        }
      }
    }

    container.addEventListener('keydown', onKeydown);

    // Move focus inside on the next frame so the container is laid out/visible.
    requestAnimationFrame(function() {
      var focusable = window.DCS._focusable(container);
      if (focusable.length) {
        focusable[0].focus();
      } else {
        if (!container.hasAttribute('tabindex')) container.setAttribute('tabindex', '-1');
        container.focus();
      }
    });

    return function release() {
      container.removeEventListener('keydown', onKeydown);
      if (previouslyFocused && typeof previouslyFocused.focus === 'function') {
        previouslyFocused.focus();
      }
    };
  };

  // ── Theme Toggle ────────────────────────────────────────
  var THEME_KEY = 'dcs-theme';
  var themeGlobalWired = false;

  function currentTheme() {
    return document.documentElement.getAttribute('data-theme') === 'light' ? 'light' : 'dark';
  }

  // Sync icon + label on EVERY theme toggle button on the page.
  // Supports generated markup (.theme-toggle-icon / .theme-toggle-label)
  // and legacy demo specimens ([data-theme-icon] / [data-theme-label]).
  function syncAllButtons() {
    var theme = currentTheme();
    var icon = theme === 'light' ? '\uD83C\uDF19' : '\u2600\uFE0F'; // 🌙 : ☀️
    var label = theme === 'light' ? 'DARK' : 'LIGHT';
    var btns = document.querySelectorAll('[data-theme-toggle]');
    for (var i = 0; i < btns.length; i++) {
      var ic = btns[i].querySelector('.theme-toggle-icon') || btns[i].querySelector('[data-theme-icon]');
      var lb = btns[i].querySelector('.theme-toggle-label') || btns[i].querySelector('[data-theme-label]');
      if (ic) ic.textContent = icon;
      if (lb) lb.textContent = label;
      // Ensure an accessible name + pressed state on every toggle button.
      if (!btns[i].getAttribute('aria-label')) {
        btns[i].setAttribute('aria-label', 'Toggle light and dark theme');
      }
      btns[i].setAttribute('aria-pressed', theme === 'light' ? 'true' : 'false');
    }
  }

  function applyTheme(theme) {
    document.documentElement.setAttribute('data-theme', theme);
    try { localStorage.setItem(THEME_KEY, theme); } catch (e) {}
    syncAllButtons();
  }

  // Wire page-level theme behavior exactly once.
  // Uses capture-phase delegation so we catch clicks before
  // any bubble-phase handlers that might double-toggle.
  function wireThemeGlobal() {
    if (themeGlobalWired) return;
    themeGlobalWired = true;

    // Restore saved preference on first init.
    var saved = null;
    try { saved = localStorage.getItem(THEME_KEY); } catch (e) {}
    if (saved === 'light' || saved === 'dark') {
      applyTheme(saved);
    } else {
      syncAllButtons();
    }

    // Capture-phase delegation: catches clicks on ANY theme toggle button.
    // Stopping propagation prevents legacy per-button handlers from
    // double-toggling.
    document.addEventListener('click', function(e) {
      var btn = e.target && e.target.closest ? e.target.closest('[data-theme-toggle]') : null;
      if (!btn) return;
      e.preventDefault();
      e.stopPropagation();
      applyTheme(currentTheme() === 'light' ? 'dark' : 'light');
    }, true);
  }

  // ── Theme Component Registration ────────────────────────
  // Pages with <div data-dcs-component="theme"> get an auto-injected
  // toggle button. Pages without it still get global theme wiring
  // via wireThemeGlobal() below.
  window.DCS.register('theme', {
    init: function(el) {
      var btn = el.querySelector('[data-theme-toggle]');
      if (!btn) {
        el.innerHTML =
          '<button data-theme-toggle class="theme-toggle-btn" aria-label="Toggle light and dark theme">' +
            '<span class="theme-toggle-icon">\u2600\uFE0F</span>' +
            '<span class="theme-toggle-label">LIGHT</span>' +
          '</button>';
      }
      wireThemeGlobal();
      syncAllButtons();
    }
  });

  // Also wire global theme on load (so pages without a theme component still work).
  wireThemeGlobal();

  // ── Auto-Init ───────────────────────────────────────────
  // _init() is idempotent — skips already-initialized elements.
  // Fire on multiple events to catch components registered after early DOM ready.
  function initAll() {
    wireThemeGlobal();
    window.DCS._init();
  }

  if (document.readyState === 'complete' || document.readyState === 'interactive') {
    initAll();
  } else {
    document.addEventListener('DOMContentLoaded', initAll);
  }

  // Belt and suspenders: retry on full load + after 500ms pause
  window.addEventListener('load', function() { window.DCS._init(); });
  setTimeout(function() { window.DCS._init(); }, 500);
})();

'use strict';

if (typeof window.DCS === 'undefined') {
  console.warn('DCS registry missing');
} else {
  window.DCS.register('accordion', {
    init: function(el) {
      var mode = el.getAttribute('data-accordion-mode') || 'multi';
      var items = el.querySelectorAll('.accordion-item');
      var triggers = [];
      var uid = 'acc-' + Math.random().toString(36).substr(2, 8);

      // Initialize each item — set up ARIA and pre-open state
      for (var i = 0; i < items.length; i++) {
        (function(item, index) {
          var trigger = item.querySelector('.accordion-trigger');
          var content = item.querySelector('.accordion-content');
          if (!trigger || !content) return;

          // Generate IDs for ARIA linkage
          var triggerId = uid + '-trigger-' + index;
          var contentId = uid + '-content-' + index;
          trigger.id = triggerId;
          content.id = contentId;

          // ARIA attributes
          trigger.setAttribute('aria-expanded', String(item.classList.contains('open')));
          trigger.setAttribute('aria-controls', contentId);
          content.setAttribute('role', 'region');
          content.setAttribute('aria-labelledby', triggerId);

          triggers.push(trigger);

          // Pre-opened items need their maxHeight set on init
          if (item.classList.contains('open')) {
            content.style.maxHeight = content.scrollHeight + 'px';
          }
        })(items[i], i);
      }

      // Click delegation
      el.addEventListener('click', function(e) {
        var trigger = e.target.closest('.accordion-trigger');
        if (!trigger) return;
        toggleItem(trigger, mode);
      });

      // Keyboard navigation
      el.addEventListener('keydown', function(e) {
        var trigger = e.target ? e.target.closest('.accordion-trigger') : null;
        var key = e.key;

        if (!trigger) {
          if (key === 'ArrowDown' || key === 'ArrowUp' || key === 'Home' || key === 'End') {
            trigger = document.activeElement && document.activeElement.closest
              ? document.activeElement.closest('.accordion-trigger')
              : null;
          }
        }

        if (!trigger) return;

        var idx = triggers.indexOf(trigger);
        if (idx === -1) return;

        if (key === 'ArrowDown') {
          e.preventDefault();
          triggers[(idx + 1) % triggers.length].focus();
        } else if (key === 'ArrowUp') {
          e.preventDefault();
          triggers[(idx - 1 + triggers.length) % triggers.length].focus();
        } else if (key === 'Home') {
          e.preventDefault();
          triggers[0].focus();
        } else if (key === 'End') {
          e.preventDefault();
          triggers[triggers.length - 1].focus();
        }
      });

      function toggleItem(trigger, mode) {
        var item = trigger.closest('.accordion-item');
        var content = item.querySelector('.accordion-content');
        if (!item || !content) return;

        var isOpen = item.classList.contains('open');

        // Single-select: close all siblings before opening
        if (mode === 'single' && !isOpen) {
          var openItems = el.querySelectorAll('.accordion-item.open');
          for (var i = 0; i < openItems.length; i++) {
            closeItem(openItems[i]);
          }
        }

        if (isOpen) {
          closeItem(item);
        } else {
          openItem(item);
        }
      }

      function openItem(item) {
        var content = item.querySelector('.accordion-content');
        var trigger = item.querySelector('.accordion-trigger');
        item.classList.add('open');
        // Set to scrollHeight first, then clear after transition so dynamic content works
        content.style.maxHeight = content.scrollHeight + 'px';
        if (trigger) trigger.setAttribute('aria-expanded', 'true');
      }

      function closeItem(item) {
        var content = item.querySelector('.accordion-content');
        var trigger = item.querySelector('.accordion-trigger');
        content.style.maxHeight = '0px';
        item.classList.remove('open');
        if (trigger) trigger.setAttribute('aria-expanded', 'false');
      }
    }
  });
}

'use strict';

if (typeof window.DCS === 'undefined') {
  console.warn('DCS registry missing');
} else {
  window.DCS.register('alerts', {
    init: function(el) {
      // el wraps both the banner stack and the "Restore All Banners" button.
      el.addEventListener('click', function(e) {
        // ── Restore all dismissed banners ──────────────────
        var restoreBtn = e.target.closest('[data-action="restore-alerts"]');
        if (restoreBtn) {
          var banners = el.querySelectorAll('.alert-banner');
          for (var i = 0; i < banners.length; i++) {
            if (banners[i].style.display === 'none') {
              banners[i].style.display = '';
              banners[i].classList.remove('dismissing');
            }
          }
          if (window.DCS._showToast) {
            window.DCS._showToast('All banners restored', 'info');
          }
          return;
        }

        // ── Dismiss a single banner ────────────────────────
        var dismissBtn = e.target.closest('.alert-dismiss') || e.target.closest('.alert-banner-dismiss');
        if (!dismissBtn) return;

        var banner = dismissBtn.closest('.alert-banner');
        if (!banner) return;

        banner.classList.add('dismissing');
        setTimeout(function() {
          banner.style.display = 'none';
        }, 360);

        if (window.DCS._showToast) {
          window.DCS._showToast('Alert dismissed', 'info');
        }
      });
    }
  });
}

'use strict';

if (typeof window.DCS === 'undefined') {
  console.warn('DCS registry missing');
} else {
  window.DCS.register('badges', {
    init: function(el) {
      el.addEventListener('click', function(e) {
        // 1. Dismissible badge: click on the dismiss control removes the badge.
        var dismiss = e.target.closest('.badge-dismiss');
        if (dismiss) {
          var dismissible = dismiss.closest('.badge--dismissible');
          if (dismissible) {
            var label = dismissible.textContent.replace(/[×✕✖x]\s*$/i, '').trim();
            dismissible.classList.add('badge--removing');
            setTimeout(function() {
              if (dismissible.parentNode) {
                dismissible.parentNode.removeChild(dismissible);
              }
            }, 150);
            showToast('Badge dismissed: ' + label, 'info');
          }
          return;
        }

        // 2. Status switcher buttons.
        var statusBtn = e.target.closest('[data-action="update-status"]');
        if (statusBtn) {
          var status = statusBtn.getAttribute('data-status');
          var color = statusBtn.getAttribute('data-color');
          if (window.DCS.updateGlobalStatus) {
            window.DCS.updateGlobalStatus(status, color);
          } else {
            showToast('Status changed to: ' + status, 'success');
          }
          return;
        }

        // 3. Ribbon is decorative — clicking the wrapper does nothing.
        if (e.target.closest('.badge-ribbon-wrapper')) {
          return;
        }

        // 4. Count badge: toggle active state.
        var count = e.target.closest('.badge--count, .badge--counter');
        if (count) {
          count.classList.toggle('is-active');
          return;
        }

        // 5. Any other badge acts as a filter toggle.
        var badge = e.target.closest('.badge');
        if (badge) {
          badge.classList.toggle('is-active');
          return;
        }
      });
    }
  });
}

function showToast(message, type) {
  if (window.DCS && window.DCS._showToast) {
    window.DCS._showToast(message, type);
  } else if (window._showToast) {
    window._showToast(message, type);
  }
}

'use strict';

if (typeof window.DCS === 'undefined') {
  console.warn('DCS registry missing');
} else {
  window.DCS.register('bottom-sheet', {
    init: function(el) {
      var sheet = el.querySelector('.bottom-sheet');
      var handle = el.querySelector('.bottom-sheet-drag-handle');

      // --- open / close ---
      function open() { el.classList.add('open'); }
      function close() { el.classList.remove('open'); }

      // --- drag-to-dismiss ---
      var drag = { on: false, moved: false, startY: 0, offset: 0, height: 0, skip: false };

      function dragStart(e) {
        if (!el.classList.contains('open')) return;
        drag.on = true; drag.moved = false;
        drag.startY = e.clientY; drag.offset = 0;
        drag.height = sheet.offsetHeight;
        sheet.style.transition = 'none';
        if (handle.setPointerCapture) handle.setPointerCapture(e.pointerId);
      }

      function dragMove(e) {
        if (!drag.on) return;
        var dy = e.clientY - drag.startY;
        if (!drag.moved && Math.abs(dy) > 3) drag.moved = true;
        if (dy < 0) dy = Math.max(dy * 0.3, -50);
        dy = Math.min(dy * 0.85, drag.height);
        drag.offset = dy;
        sheet.style.transform = 'translateY(' + dy + 'px)';
      }

      function dragEnd(e) {
        if (!drag.on) return;
        drag.on = false;
        if (handle.releasePointerCapture && e.pointerId !== undefined) {
          try { handle.releasePointerCapture(e.pointerId); } catch (_) {}
        }
        if (!drag.moved) { sheet.style.transition = ''; sheet.style.transform = ''; return; }
        drag.skip = true;
        if (drag.offset > Math.min(drag.height * 0.3, 100)) {
          close();
          sheet.offsetHeight; // force layout flush
        }
        sheet.style.transition = '';
        sheet.style.transform = '';
      }

      function dragCancel() {
        if (!drag.on) return;
        drag.on = false;
        sheet.style.transition = '';
        sheet.style.transform = '';
      }

      if (handle) {
        handle.addEventListener('pointerdown', dragStart);
        handle.addEventListener('pointermove', dragMove);
        handle.addEventListener('pointerup', dragEnd);
        handle.addEventListener('pointercancel', dragCancel);
      }

      // --- click delegation ---
      el.addEventListener('click', function(e) {
        if (drag.skip) { drag.skip = false; return; }
        if (e.target.closest('[data-action="sheet-open"]')) { open(); return; }
        if (e.target.closest('[data-action="sheet-close"]')) { close(); return; }
      });

      // --- escape key ---
      document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape' && el.classList.contains('open')) close();
      });
    }
  });
}

'use strict';

if (typeof window.DCS === 'undefined') {
  console.warn('DCS registry missing');
} else {
  window.DCS.register('breadcrumbs', {
    init: function(el) {
      // Mark the final crumb as the current page for screen readers.
      var items = el.querySelectorAll('.breadcrumb-item');
      if (items.length) {
        var last = items[items.length - 1];
        var target = last.querySelector('.breadcrumb-link') || last;
        target.setAttribute('aria-current', 'page');
      }

      el.addEventListener('click', function(e) {
        var link = e.target.closest('.breadcrumb-link');
        if (!link) return;

        var dest = link.getAttribute('title') || link.textContent || link.innerText || '';
        dest = dest.trim();
        if (dest.indexOf('🏠') === 0) {
          dest = dest.replace('🏠', '').trim();
        }

        if (window.DCS._showToast) {
          window.DCS._showToast('NAVIGATING: ' + dest, 'info');
        } else if (window._showToast) {
          window.DCS._showToast('NAVIGATING: ' + dest, 'info');
        }
      });
    }
  });
}

'use strict';

if (typeof window.DCS === 'undefined') {
  console.warn('DCS registry missing');
} else {
  window.DCS.register('buttons', {
    init: function(el) {
      el.addEventListener('click', function(e) {
        var btn = e.target.closest('.btn');
        if (!btn || btn.hasAttribute('disabled')) return;

        var label = btn.textContent.trim();

        if (window.DCS.triggerButtonToast) {
          var type = 'info';
          if (label === 'Start Job') {
            type = 'success';
          } else if (label === 'Export G-Code') {
            type = 'info';
          } else if (label === 'Cancel') {
            type = 'warning';
          }
          window.DCS.triggerButtonToast(label, type);
        } else if (window.DCS._showToast) {
          window.DCS._showToast('Action Triggered: ' + label, 'info');
        } else if (window._showToast) {
          window.DCS._showToast('Action Triggered: ' + label, 'info');
        }
      });
    }
  });
}

'use strict';

if (typeof window.DCS === 'undefined') {
  console.warn('DCS registry missing');
} else {
  window.DCS.register('cards', {
    init: function(el) {
      el.addEventListener('click', function(e) {
        var card = e.target.closest('.card-interactive');
        if (!card) return;

        var allCards = el.querySelectorAll('.card-interactive');
        for (var i = 0; i < allCards.length; i++) {
          allCards[i].classList.remove('card-active');
        }
        card.classList.add('card-active');
      });
    }
  });
}

'use strict';

if (typeof window.DCS === 'undefined') {
  console.warn('DCS registry missing');
} else {
  window.DCS.register('carousel', {
    init: function(el) {
      var slides = el.querySelectorAll('.dcs-carousel-slide');
      var prev = el.querySelector('.dcs-carousel-prev');
      var next = el.querySelector('.dcs-carousel-next');
      var dots = el.querySelectorAll('.dcs-carousel-dot');
      if (slides.length === 0) return;

      var current = 0;
      var autoplayInterval = 4000;
      var timer = null;
      var progress = null;
      // Respect reduced-motion: never autoplay if the user prefers reduced motion.
      var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var autoplayEnabled = el.getAttribute('data-autoplay') !== 'false' && !reduceMotion;
      var cardsVisible = parseInt(el.getAttribute('data-cards-visible'), 10) || 1;
      var multiMode = cardsVisible > 1;

      // ── ARIA: identify the carousel and label its controls ──
      el.setAttribute('aria-roledescription', 'carousel');
      if (!el.getAttribute('aria-label') && !el.getAttribute('aria-labelledby')) {
        el.setAttribute('aria-label', 'Carousel');
      }
      var liveRegion = el.querySelector('.dcs-carousel-track') || el;
      // Announce slide changes only when the user drives navigation; keep it
      // silent while autoplay is running so a screen reader isn't spammed.
      liveRegion.setAttribute('aria-live', autoplayEnabled ? 'off' : 'polite');
      for (var sa = 0; sa < slides.length; sa++) {
        slides[sa].setAttribute('role', 'group');
        slides[sa].setAttribute('aria-roledescription', 'slide');
        slides[sa].setAttribute('aria-label', (sa + 1) + ' of ' + slides.length);
      }
      if (prev) prev.setAttribute('aria-label', 'Previous slide');
      if (next) next.setAttribute('aria-label', 'Next slide');
      for (var dl = 0; dl < dots.length; dl++) {
        dots[dl].setAttribute('aria-label', 'Go to slide ' + (dl + 1));
      }

      // Create progress bar — append to active slide's image area
      progress = document.createElement('div');
      progress.className = 'dcs-carousel-progress';

      function showSlide(index) {
        if (multiMode) {
          var totalPages = Math.ceil(slides.length / cardsVisible);
          if (index < 0) index = totalPages - 1;
          if (index >= totalPages) index = 0;
          current = index;
          // Scroll the track to the correct page
          var track = el.querySelector('.dcs-carousel-track');
          if (track) {
            track.scrollTo({ left: index * track.clientWidth, behavior: 'smooth' });
          }
          resetProgress();
          return;
        }
        // Original single-slide logic
        if (index < 0) index = slides.length - 1;
        if (index >= slides.length) index = 0;
        for (var i = 0; i < slides.length; i++) {
          slides[i].classList.toggle('is-active', i === index);
          slides[i].setAttribute('aria-hidden', i === index ? 'false' : 'true');
        }
        for (var j = 0; j < dots.length; j++) {
          dots[j].classList.toggle('is-active', j === index);
        }
        if (prev) prev.disabled = false;
        if (next) next.disabled = false;
        current = index;
        // Move progress bar to active slide's image
        if (progress && slides[index]) {
          var img = slides[index].querySelector('.dcs-carousel-image');
          if (img) img.appendChild(progress);
        }
        resetProgress();
      }

      function nextSlide() { showSlide(current + 1); }
      function prevSlide() { showSlide(current - 1); }

      // Progress bar animation
      var progressRAF = null;
      var progressStart = 0;
      function resetProgress() {
        if (!autoplayEnabled) return;
        if (progressRAF) cancelAnimationFrame(progressRAF);
        progress.style.transition = 'none';
        progress.style.width = '0%';
        progressStart = performance.now();
        progressRAF = requestAnimationFrame(animateProgress);
      }
      function animateProgress(timestamp) {
        if (!progressStart) progressStart = timestamp;
        var elapsed = timestamp - progressStart;
        var pct = Math.min((elapsed / autoplayInterval) * 100, 100);
        progress.style.transition = 'none';
        progress.style.width = pct + '%';
        if (pct < 100) {
          progressRAF = requestAnimationFrame(animateProgress);
        }
      }

      // Autoplay
      function startAutoplay() {
        if (!autoplayEnabled) return;
        stopAutoplay();
        resetProgress();
        timer = setInterval(function() {
          nextSlide();
        }, autoplayInterval);
      }
      function stopAutoplay() {
        if (timer) { clearInterval(timer); timer = null; }
        if (progressRAF) { cancelAnimationFrame(progressRAF); progressRAF = null; }
      }

      // Pause on hover
      el.addEventListener('mouseenter', function() {
        el.classList.add('is-paused');
        stopAutoplay();
      });
      el.addEventListener('mouseleave', function() {
        el.classList.remove('is-paused');
        startAutoplay();
      });

      // Arrows
      if (prev) prev.addEventListener('click', prevSlide);
      if (next) next.addEventListener('click', nextSlide);

      // Dots
      for (var d = 0; d < dots.length; d++) {
        (function(i) {
          dots[i].addEventListener('click', function() { showSlide(i); });
        })(d);
      }

      // Multi-mode: scroll listener to update dots on drag/swipe
      if (multiMode) {
        var trackEl = el.querySelector('.dcs-carousel-track');
        var scrollTimeout;
        trackEl.addEventListener('scroll', function() {
          if (!trackEl.clientWidth) return;
          clearTimeout(scrollTimeout);
          scrollTimeout = setTimeout(function() {
            var newPage = Math.round(trackEl.scrollLeft / trackEl.clientWidth);
            var totalPages = Math.ceil(slides.length / cardsVisible);
            if (newPage !== current && newPage >= 0 && newPage < totalPages) {
              current = newPage;
              for (var d = 0; d < dots.length; d++) {
                dots[d].classList.toggle('is-active', d === current);
              }
              resetProgress();
            }
          }, 150);
        });
      }

      // Keyboard
      el.setAttribute('tabindex', '0');
      el.addEventListener('keydown', function(e) {
        if (e.key === 'ArrowLeft') { e.preventDefault(); prevSlide(); }
        else if (e.key === 'ArrowRight') { e.preventDefault(); nextSlide(); }
      });

      // Touch swipe
      var touchStartX = 0;
      el.addEventListener('touchstart', function(e) {
        touchStartX = e.touches[0].clientX;
      });
      el.addEventListener('touchend', function(e) {
        var diff = touchStartX - e.changedTouches[0].clientX;
        if (Math.abs(diff) > 50) {
          if (diff > 0) nextSlide();
          else prevSlide();
        }
      });

      // Init
      if (multiMode) {
        // All slides visible in multi-mode — mark them active
        for (var s = 0; s < slides.length; s++) {
          slides[s].classList.add('is-active');
        }
        if (dots.length > 0) dots[0].classList.add('is-active');
      }
      showSlide(0);
      // Only autoplay if not explicitly disabled
      if (autoplayEnabled) {
        startAutoplay();
      } else if (progress && progress.parentNode) {
        progress.parentNode.removeChild(progress);
      }
    }
  });
}

'use strict';

console.log('[DCS] checkboxes controller loaded');

if (typeof window.DCS === 'undefined') {
  console.warn('DCS registry missing');
} else {
  window.DCS.register('checkboxes', {
    init: function(el) {
      // Find parent-child checkbox groups
      var parentInput = el.querySelector('#parent-input');
      if (!parentInput) return;

      var childCheckboxes = el.querySelectorAll('input[type="checkbox"]:not(#parent-input)');

      function updateParentState() {
        var checkedCount = 0;
        var total = 0;
        childCheckboxes.forEach(function(cb) {
          if (!cb.disabled) total++;
          if (cb.checked) checkedCount++;
        });

        if (checkedCount === 0) {
          parentInput.indeterminate = false;
          parentInput.checked = false;
        } else if (checkedCount === total) {
          parentInput.indeterminate = false;
          parentInput.checked = true;
        } else {
          parentInput.indeterminate = true;
          parentInput.checked = false;
        }
      }

      // Initialize indeterminate state
      updateParentState();

      // Parent toggles all children
      parentInput.addEventListener('change', function() {
        var newState = parentInput.checked;
        childCheckboxes.forEach(function(cb) {
          if (!cb.disabled) {
            cb.checked = newState;
          }
        });
        parentInput.indeterminate = false;
      });

      // Child changes update parent
      childCheckboxes.forEach(function(cb) {
        cb.addEventListener('change', updateParentState);
      });
    }
  });
}

'use strict';

if (typeof window.DCS === 'undefined') {
  console.warn('DCS registry is undefined. dcs-chips.js could not register the chips component.');
} else {
  window.DCS.register('chips', {
    init: function(el) {
      // el is the chips container [data-dcs-component="chips"]
      var input = el.querySelector('[data-chip-input]');

      // Remove a chip when its close button is clicked
      el.addEventListener('click', function(e) {
        var close = e.target.closest('.chip-close');
        if (!close) {
          return;
        }
        var chip = close.closest('.chip');
        if (chip && chip.parentNode) {
          chip.parentNode.removeChild(chip);
        }
      });

      if (!input) {
        return;
      }

      // Create a new chip on Enter
      input.addEventListener('keydown', function(e) {
        if (e.key !== 'Enter') {
          return;
        }
        e.preventDefault();
        var value = input.value.trim();
        if (!value) {
          return;
        }

        var chip = document.createElement('div');
        chip.className = 'chip';

        var text = document.createElement('span');
        text.textContent = value;

        var close = document.createElement('span');
        close.className = 'chip-close';
        close.innerHTML = '&times;';

        chip.appendChild(text);
        chip.appendChild(close);

        el.insertBefore(chip, input);
        input.value = '';
      });
    }
  });
}

'use strict';

if (typeof window.DCS === 'undefined') {
  console.warn('DCS registry is undefined. dcs-clipboard.js could not register the clipboard component.');
} else {
  window.DCS.register('clipboard', {
    init: function(el) {
      var restoreTimer = null;

      function flash(text, ok) {
        var original = el.getAttribute('data-clipboard-original');
        if (original === null) {
          original = el.textContent;
          el.setAttribute('data-clipboard-original', original);
        }
        if (restoreTimer) clearTimeout(restoreTimer);
        el.textContent = text;
        el.classList.toggle('copied', !!ok);
        restoreTimer = setTimeout(function() {
          el.textContent = el.getAttribute('data-clipboard-original');
          el.classList.remove('copied');
        }, 2000);
      }

      function onSuccess() {
        flash('Copied!', true);
        if (window.DCS && typeof window.DCS._showToast === 'function') {
          window.DCS._showToast('Copied to clipboard', 'success');
        }
      }

      function onError() {
        flash('Failed', false);
        if (window.DCS && typeof window.DCS._showToast === 'function') {
          window.DCS._showToast('Copy failed', 'error');
        }
      }

      el.addEventListener('click', function() {
        var text = el.hasAttribute('data-clipboard-text')
          ? el.getAttribute('data-clipboard-text')
          : el.textContent;

        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(text).then(onSuccess, onError);
        } else {
          onError();
        }
      });
    }
  });
}

