if (typeof window.DCS === 'undefined') {
  console.warn('DCS registry is undefined. dcs-progress.js could not register the progress component.');
} else {
  window.DCS.register('progress', {
    init: function(el) {
      // Circular variant: the component element is itself the ring. Drive the
      // conic-gradient (see progress-ring.css) from data-* attributes rather
      // than from a child fill's width.
      if (el.classList.contains('dcs-progress-ring')) {
        var value = parseFloat(el.getAttribute('data-progress-value')) || 0;
        var max = parseFloat(el.getAttribute('data-progress-max')) || 100;
        var pct = max > 0 ? Math.max(0, Math.min(100, (value / max) * 100)) : 0;
        var size = parseFloat(el.getAttribute('data-progress-size')) || 80;
        var strokeAttr = el.getAttribute('data-progress-stroke');
        var strokePx = (parseFloat(strokeAttr) || 6) + 'px';
        var ringColor = el.getAttribute('data-progress-color');

        el.style.width = size + 'px';
        el.style.height = size + 'px';
        el.style.setProperty('--ring-pct', String(Math.round(pct)));
        el.style.setProperty('--ring-stroke', strokePx);
        if (ringColor) el.style.setProperty('--ring-color', ringColor);

        // Keep ARIA in step with the rendered value.
        el.setAttribute('aria-valuenow', String(Math.round(value)));
        if (!el.getAttribute('aria-valuemin')) el.setAttribute('aria-valuemin', '0');
        if (!el.getAttribute('aria-valuemax')) el.setAttribute('aria-valuemax', String(Math.round(max)));
        if (!el.getAttribute('role')) el.setAttribute('role', 'progressbar');
        return;
      }

      // Expose each determinate bar as a progressbar. The visible fill width
      // (set inline as a percentage) is the source of truth for aria-valuenow.
      var bars = el.querySelectorAll('.progress-bar-container');
      for (var i = 0; i < bars.length; i++) {
        (function(bar) {
          var fill = bar.querySelector('.progress-bar-fill');
          if (!fill) return;

          bar.setAttribute('role', 'progressbar');
          bar.setAttribute('aria-valuemin', '0');
          bar.setAttribute('aria-valuemax', '100');
          if (!bar.getAttribute('aria-label')) bar.setAttribute('aria-label', 'Progress');

          // Indeterminate mode: no value, just a continuous CSS animation.
          if (bar.hasAttribute('data-progress-indeterminate')) {
            bar.classList.add('is-indeterminate');
            bar.removeAttribute('aria-valuenow');
            return;
          }

          // Optional textual label ("3/8 · 42%") rendered into a sibling
          // .dcs-progress-label within the bar's parent wrapper.
          var label = null;
          if (bar.hasAttribute('data-progress-label') && bar.parentNode) {
            label = bar.parentNode.querySelector('.dcs-progress-label');
          }

          function sync() {
            var pct = Math.round(parseFloat(fill.style.width) || 0);
            bar.setAttribute('aria-valuenow', String(pct));
            if (label) {
              var value = bar.getAttribute('data-progress-value');
              var max = bar.getAttribute('data-progress-max');
              if (value !== null && max !== null) {
                label.textContent = value + '/' + max + ' · ' + pct + '%';
              } else {
                label.textContent = pct + '%';
              }
            }
          }
          sync();

          // Keep aria-valuenow in step with any animated width changes.
          if (window.MutationObserver) {
            var mo = new MutationObserver(sync);
            mo.observe(fill, { attributes: true, attributeFilter: ['style'] });
          }
        })(bars[i]);
      }
    }
  });
}

'use strict';

if (typeof window.DCS === 'undefined') {
  console.warn('DCS registry is undefined. dcs-radio.js could not register the radio-group component.');
} else {
  window.DCS.register('radio-group', {
    init: function(el) {
      // A group may share a `name` across sibling containers (segmented
      // layouts). When data-radio-name is present, gather every matching
      // input; otherwise fall back to the inputs inside this container.
      var name = el.getAttribute('data-radio-name');
      var inputs;
      if (name) {
        inputs = Array.prototype.slice.call(
          el.querySelectorAll('input[type="radio"][name="' + name + '"]')
        );
      } else {
        inputs = Array.prototype.slice.call(el.querySelectorAll('input[type="radio"]'));
      }
      if (!inputs.length) return;

      function labelFor(input) {
        var label = input.closest ? input.closest('.dcs-radio') : null;
        var text = label ? label.querySelector('.dcs-radio-label') : null;
        return text ? text.textContent.trim() : input.value;
      }

      function emit(input) {
        el.dispatchEvent(new CustomEvent('dcs-radio-change', {
          bubbles: true,
          detail: { value: input.value, label: labelFor(input), input: input }
        }));
      }

      function focusByOffset(current, delta) {
        var idx = inputs.indexOf(current);
        if (idx === -1) return;
        var next = inputs[(idx + delta + inputs.length) % inputs.length];
        if (next.disabled) return;
        next.checked = true;
        next.focus();
        emit(next);
      }

      el.addEventListener('change', function(e) {
        var input = e.target;
        if (input && input.type === 'radio' && inputs.indexOf(input) !== -1) {
          emit(input);
        }
      });

      el.addEventListener('keydown', function(e) {
        var input = e.target;
        if (!input || input.type !== 'radio' || inputs.indexOf(input) === -1) return;
        if (e.key === 'ArrowDown' || e.key === 'ArrowRight') {
          e.preventDefault();
          focusByOffset(input, 1);
        } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') {
          e.preventDefault();
          focusByOffset(input, -1);
        }
      });
    }
  });
}

'use strict';

// DCS Scrollspy — dual-mode: main sidebar nav + inline demo TOC
// Auto-detects which mode based on child elements.
// Mode A: Main sidebar — .sidebar-item[data-section] → #section-id, scrolls with viewport
// Mode B: Inline demo — .toc-item[data-target] → [data-spy-target], scrolls within content area
//
// Algorithm: position-based, NOT index-based. Targets are sorted by their visual
// (DOM) position. On scroll, picks the target whose section top is CLOSEST to the
// threshold from below — i.e. the section most recently scrolled into view.
// This is correct regardless of sidebar ordering.

if (typeof window.DCS === 'undefined') {
  console.warn('DCS registry missing — scrollspy not registered');
} else {
  window.DCS.register('scrollspy', {
    init: function(el) {
      // ── Detect mode ─────────────────────────────────────
      var items, scrollSource, getTargetId, itemSelector, activeClass;

      var sidebarItems = el.querySelectorAll('.sidebar-item');
      var tocItems = el.querySelectorAll('.toc-item');
      var contentArea = el.querySelector('[data-scrollspy-content]');

      if (sidebarItems.length) {
        // Mode A: Main sidebar nav — tracks viewport scroll
        items = sidebarItems;
        scrollSource = null; // window
        getTargetId = function(item) {
          var id = item.getAttribute('data-section');
          return id || null;
        };
        itemSelector = '.sidebar-item';
        activeClass = 'active';
      } else if (tocItems.length && contentArea) {
        // Mode B: Inline demo TOC — tracks content-area scroll
        items = tocItems;
        scrollSource = contentArea;
        getTargetId = function(item) {
          return item.getAttribute('data-target');
        };
        itemSelector = '.toc-item';
        activeClass = 'active';
      } else {
        return; // nothing to track
      }

      // ── Build target map (sorted by visual DOM position) ─
      var targets = [];
      for (var i = 0; i < items.length; i++) {
        var targetId = getTargetId(items[i]);
        if (!targetId) continue;
        var targetEl;
        if (scrollSource === null) {
          targetEl = document.getElementById(targetId);
        } else {
          targetEl = el.querySelector('[data-spy-target="' + targetId + '"]');
        }
        if (targetEl) {
          targets.push({ item: items[i], target: targetEl, id: targetId });
        }
      }

      if (!targets.length) return;

      // Sort targets by their actual DOM position (top-to-bottom visual order)
      // This ensures iteration order matches visual flow, regardless of sidebar ordering
      targets.sort(function(a, b) {
        var aTop, bTop;
        if (scrollSource === null) {
          aTop = a.target.getBoundingClientRect().top + window.scrollY;
          bTop = b.target.getBoundingClientRect().top + window.scrollY;
        } else {
          aTop = a.target.offsetTop;
          bTop = b.target.offsetTop;
        }
        return aTop - bTop;
      });

      // ── Set active item ─────────────────────────────────
      function setActive(targetItem) {
        var current = el.querySelectorAll(itemSelector);
        for (var i = 0; i < current.length; i++) {
          if (current[i] === targetItem) {
            current[i].classList.add(activeClass);
          } else {
            current[i].classList.remove(activeClass);
          }
        }
      }

      // ── Scroll handler ──────────────────────────────────
      var scrollTicking = false;
      function onScroll() {
        if (scrollTicking) return;
        scrollTicking = true;
        requestAnimationFrame(function() {
          scrollTicking = false;
          doScrollCheck();
        });
      }

      function doScrollCheck() {
        var viewTop, scrollThreshold;

        if (scrollSource === null) {
          viewTop = window.scrollY;
        } else {
          viewTop = scrollSource.scrollTop;
        }

        // Threshold: how far below the viewport top a section can start
        // and still be considered "active." Use 33% of viewport height so that
        // a section becomes active shortly after its top enters the viewport,
        // not just when it hits pixel 0.
        var viewHeight = scrollSource === null ? window.innerHeight : scrollSource.clientHeight;
        scrollThreshold = Math.round(viewHeight * 0.33);

        var activeTarget = null;
        var bestRefTop = -Infinity;

        // Determine the bottom of the scrollable area (for last-section detection)
        var docHeight = scrollSource === null
          ? document.documentElement.scrollHeight
          : scrollSource.scrollHeight;
        var atBottom = (viewTop + viewHeight) >= (docHeight - 2);

        for (var i = 0; i < targets.length; i++) {
          var rect = targets[i].target.getBoundingClientRect();
          var refTop;

          if (scrollSource === null) {
            refTop = rect.top;
          } else {
            var containerRect = scrollSource.getBoundingClientRect();
            refTop = rect.top - containerRect.top;
          }

          // Section is "active" if its top is at or above the scroll threshold.
          // We pick the one whose top is CLOSEST to the threshold (highest refTop
          // that's still ≤ threshold). This gives us the section most recently
          // scrolled into view, regardless of sidebar ordering.
          if (refTop <= scrollThreshold) {
            if (refTop > bestRefTop) {
              bestRefTop = refTop;
              activeTarget = targets[i].item;
            }
          }
        }

        // Edge case: we're at the very bottom of the page. The last section
        // might not reach the threshold if it's very short. Fall back to the
        // last target in visual order.
        if (atBottom && targets.length) {
          // Check if the current best is actually the last section
          var lastTarget = targets[targets.length - 1].item;
          var lastRect = targets[targets.length - 1].target.getBoundingClientRect();
          var lastRefTop = scrollSource === null ? lastRect.top : lastRect.top - scrollSource.getBoundingClientRect().top;
          // If last section is visible in the viewport, make it active
          if (lastRefTop < viewHeight) {
            activeTarget = lastTarget;
          }
        }

        // Fallback: nothing above threshold → highlight first item (top of page)
        if (!activeTarget && targets.length) {
          activeTarget = targets[0].item;
        }

        if (activeTarget) {
          setActive(activeTarget);
        }
      }

      // ── Wire scroll ─────────────────────────────────────
      if (scrollSource === null) {
        window.addEventListener('scroll', onScroll, { passive: true });
      } else {
        scrollSource.addEventListener('scroll', onScroll, { passive: true });
      }

      // ── Click handler: scroll to target ─────────────────
      el.addEventListener('click', function(e) {
        var item = e.target.closest(itemSelector);
        if (!item || !el.contains(item)) return;

        var targetId = getTargetId(item);
        if (!targetId) return;

        var targetEl;
        if (scrollSource === null) {
          targetEl = document.getElementById(targetId);
        } else {
          targetEl = el.querySelector('[data-spy-target="' + targetId + '"]');
        }

        if (targetEl) {
          e.preventDefault();
          if (scrollSource === null) {
            targetEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
          } else {
            var containerRect = scrollSource.getBoundingClientRect();
            var targetRect = targetEl.getBoundingClientRect();
            scrollSource.scrollTop += (targetRect.top - containerRect.top);
          }
          setActive(item);
        }
      });

      // ── Initial run ─────────────────────────────────────
      // Wait for fonts to load + layout to settle before positioning the indicator.
      // A fixed setTimeout is unreliable — font swap changes element widths.
      function initCheck() {
        requestAnimationFrame(function() {
          requestAnimationFrame(doScrollCheck);
        });
      }
      if (document.fonts && document.fonts.ready) {
        document.fonts.ready.then(initCheck);
      } else {
        window.addEventListener('load', initCheck);
      }
    }
  });
}

'use strict';

if (typeof window.DCS === 'undefined') {
  console.warn('DCS registry missing');
} else {
  window.DCS.register('search', {
    init: function(el) {
      var input = el.querySelector('.dcs-search-input');
      var clear = el.querySelector('.dcs-search-clear');
      if (!input) return;

      // Expose the search landmark + name the input for screen readers.
      if (!el.getAttribute('role')) el.setAttribute('role', 'search');
      if (!input.getAttribute('aria-label') && !input.getAttribute('aria-labelledby')) {
        input.setAttribute('aria-label', input.getAttribute('placeholder') || 'Search');
      }

      function sync() {
        if (input.value.length > 0) {
          el.classList.add('has-value');
        } else {
          el.classList.remove('has-value');
        }
      }

      input.addEventListener('input', sync);
      sync();

      if (clear) {
        clear.addEventListener('click', function() {
          input.value = '';
          sync();
          input.focus();
        });
      }
    }
  });
}

'use strict';

if (typeof window.DCS === 'undefined') {
  console.warn('DCS registry is undefined. dcs-segmented-control.js could not register the segmented-control component.');
} else {
  window.DCS.register('segmented-control', {
    init: function(el) {
      // el is the interactive demo wrapper [data-dcs-component="segmented-control"]
      var feedback = el.querySelector('.segmented-feedback');

      // ── ARIA: expose each control as a radiogroup of radios ──
      var groups = el.querySelectorAll('.segmented-control');
      for (var g = 0; g < groups.length; g++) {
        groups[g].setAttribute('role', 'radiogroup');
        var btns = groups[g].querySelectorAll('.segment-btn');
        for (var b = 0; b < btns.length; b++) {
          var isActive = btns[b].classList.contains('active');
          btns[b].setAttribute('role', 'radio');
          btns[b].setAttribute('aria-checked', isActive ? 'true' : 'false');
          btns[b].setAttribute('tabindex', isActive ? '0' : '-1');
        }
      }

      function activate(btn, group) {
        var siblings = group.querySelectorAll('.segment-btn');
        for (var i = 0; i < siblings.length; i++) {
          siblings[i].classList.remove('active');
          siblings[i].setAttribute('aria-checked', 'false');
          siblings[i].setAttribute('tabindex', '-1');
        }
        btn.classList.add('active');
        btn.setAttribute('aria-checked', 'true');
        btn.setAttribute('tabindex', '0');

        if (feedback) {
          var value = btn.getAttribute('data-filter') || btn.textContent;
          feedback.textContent = 'ACTIVE FILTER: ' + value.toUpperCase();
        }
      }

      el.addEventListener('click', function(e) {
        var btn = e.target.closest('.segment-btn');
        if (!btn || !el.contains(btn)) {
          return;
        }
        var group = btn.closest('.segmented-control');
        if (!group) {
          return;
        }
        activate(btn, group);
      });

      // Keyboard: arrow keys move selection within the group.
      el.addEventListener('keydown', function(e) {
        var btn = e.target.closest('.segment-btn');
        if (!btn || !el.contains(btn)) return;
        var group = btn.closest('.segmented-control');
        if (!group) return;

        var list = Array.prototype.slice.call(group.querySelectorAll('.segment-btn'));
        var idx = list.indexOf(btn);
        if (idx === -1) return;

        if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
          e.preventDefault();
          var nx = list[(idx + 1) % list.length];
          activate(nx, group); nx.focus();
        } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
          e.preventDefault();
          var pv = list[(idx - 1 + list.length) % list.length];
          activate(pv, group); pv.focus();
        }
      });
    }
  });
}

